57	// newVizCommand builds `entire brain viz` — a local, no-egress web interface
58	// that renders the brain's semantic graph. It mirrors newDashCommand's shape
59	// (dash.go) but serves a browser UI instead of a terminal TUI.
60	func newVizCommand(opts Options) *cobra.Command {
61		var flags vizFlags
62		cmd := &cobra.Command{
63			Use:   "viz [path]",
64			Short: "Explore the brain as a visual graph in your browser (local, offline)",
65			Long: `viz starts a local, no-egress web interface that renders the brain's
66	semantic graph — code entities and their CALLS/IMPORTS relations — as an
67	explorable, force-directed graph with search and a symbol inspector.
68	
69	It binds to 127.0.0.1 only, serves a self-contained embedded UI (no CDN), and
70	reads the brain from disk read-only: no agent calls, no outbound network.`,
71			Args: cobra.MaximumNArgs(1),
72			RunE: func(cmd *cobra.Command, args []string) error {
73				return runViz(cmd.Context(), cmd, opts, flags, agentSurfaceTarget(opts, args))
74			},
75		}
76		cmd.Flags().IntVar(&flags.port, "port", 0, "Port to bind on 127.0.0.1 (0 = auto-pick a free port)")
77		cmd.Flags().StringVar(&flags.branch, "branch", "", "Branch whose brain to load (default: current branch)")
78		cmd.Flags().BoolVar(&flags.noOpen, "no-open", false, "Do not open a browser automatically")
79		cmd.Flags().IntVar(&flags.limit, "limit", vizDefaultLimit, "Max symbols loaded into the graph (0 = no cap)")
80		return cmd
81	}
