83	// vizServer holds the resolved brain location for the lifetime of one server.
84	// Like the dashboard, it captures a single brain (brainDir/branch/manifest) at
85	// startup; re-run `viz` to pick up a fresh `refresh`.
86	type vizServer struct {
87		opts     Options
88		target   string
89		repoDir  string
90		brainDir string
91		branch   string
92		manifest *exportManifest
93		limit    int
94		// repo coordinates parsed from the brain key (provider/owner/repo), used to
95		// build real entire.io + source links. Empty provider = local repo (no links).
96		provider string
97		owner    string
98		repo     string
99	}
100	
101	// vizListenAddr is the bind address — loopback ONLY, never 0.0.0.0 or ::. Factored
102	// out so the no-egress invariant (unreachable off-host) is unit-testable.
103	func vizListenAddr(port int) string { return "127.0.0.1:" + strconv.Itoa(port) }
104	
105	func runViz(ctx context.Context, cmd *cobra.Command, opts Options, flags vizFlags, target string) error {
106		repoDir, brainDir, branch, err := resolveFactsTarget(ctx, opts, target, flags.branch)
107		if err != nil {
108			return err
109		}
110	
111		// Best-effort: an unbuilt brain still serves — the UI shows an empty state
112		// ("run `entire brain refresh`") rather than failing the command.
113		var manifest *exportManifest
114		if status, serr := buildBrainStatusReport(ctx, opts, target); serr == nil {
115			manifest = status.Manifest
116		}
117	
118		srv := &vizServer{opts: opts, target: target, repoDir: repoDir, brainDir: brainDir, branch: branch, manifest: manifest, limit: flags.limit}
119		srv.provider, srv.owner, srv.repo = parseRepoFromBrainDir(brainDir)
120	
121		// Loopback only — never 0.0.0.0. The interface is a personal, read-only view
122		// of local data and must not be reachable off-host.
123		ln, err := net.Listen("tcp", vizListenAddr(flags.port))
124		if err != nil {
125			return fmt.Errorf("bind viz server: %w", err)
126		}
127		url := "http://" + ln.Addr().String()
128		fmt.Fprintf(cmd.OutOrStdout(), "entire brain viz — %s\n", url)
129		fmt.Fprintln(cmd.OutOrStdout(), "Read-only, loopback-only, no network. Press Ctrl-C to stop.")
130		if !flags.noOpen {
131			openBrowser(url)
132		}
133	
134		httpSrv := &http.Server{Handler: vizSecurityHeaders(srv.mux()), ReadHeaderTimeout: 5 * time.Second}
135		go func() {
136			<-ctx.Done()
137			shutCtx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
138			defer cancel()
139			_ = httpSrv.Shutdown(shutCtx)
140		}()
141		if err := httpSrv.Serve(ln); err != nil && !errors.Is(err, http.ErrServerClosed) {
142			return fmt.Errorf("viz server: %w", err)
143		}
144		return nil
145	}
