147	func (s *vizServer) mux() http.Handler {
148		m := http.NewServeMux()
149		m.HandleFunc("/api/summary", s.handleSummary)
150		m.HandleFunc("/api/graph", s.handleGraph)
151		m.HandleFunc("/api/node", s.handleNode)
152		m.HandleFunc("/api/search", s.handleSearch)
153		m.HandleFunc("/api/facts", s.handleFacts)
154		m.HandleFunc("/api/sessions", s.handleSessions)
155		m.HandleFunc("/api/session/replay", s.handleSessionReplay)
156		m.HandleFunc("/api/history", s.handleHistory)
157		m.HandleFunc("/api/docs", s.handleDocs)
158		if sub, err := fs.Sub(entirebrain.WebUI, "webui/dist"); err == nil {
159			m.Handle("/", http.FileServer(http.FS(sub)))
160		}
161		return m
162	}
