164	// vizSecurityHeaders makes the no-egress guarantee machine-checkable: the CSP
165	// forbids any off-origin fetch (script/style/img/font/connect all 'self'), so
166	// even a compromised asset can't call home. Structural, not just a comment.
167	func vizSecurityHeaders(next http.Handler) http.Handler {
168		const csp = "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; font-src 'self'; base-uri 'none'; frame-ancestors 'none'"
169		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
170			w.Header().Set("Content-Security-Policy", csp)
171			w.Header().Set("X-Content-Type-Options", "nosniff")
172			w.Header().Set("Referrer-Policy", "no-referrer")
173			next.ServeHTTP(w, r)
174		})
175	}
