265	func (s *vizServer) handleSummary(w http.ResponseWriter, r *http.Request) {
266		resp := vizSummaryResp{Repo: s.repoDir, Branch: s.branch}
267		// Counts come straight from the manifest captured at startup. Rebuilding the
268		// full status report here costs several seconds on large brains and would
269		// block the very first paint of the hub — so we don't. loadDocIndex is cheap.
270		if m := s.manifest; m != nil && m.Sources != nil {
271			if sem := m.Sources.Semantic; sem != nil {
272				resp.Counts.Symbols = sem.Symbols
273				resp.Counts.Relations = sem.Relations
274				resp.Counts.Files = sem.Files
275				if !sem.GeneratedAt.IsZero() {
276					resp.GeneratedAt = sem.GeneratedAt.UTC().Format(time.RFC3339)
277				}
278			}
279			if h := m.Sources.History; h != nil {
280				resp.Counts.History = h.Records
281			}
282			if f := m.Sources.Facts; f != nil {
283				resp.Counts.Facts = f.Facts
284			}
285			if ss := m.Sources.Sessions; ss != nil {
286				resp.Counts.Sessions = len(ss.Sessions)
287			}
288		}
289		if docs, err := loadDocIndex(s.brainDir); err == nil {
290			resp.Counts.Docs = len(docs.Records)
291		}
292		writeJSONHTTP(w, http.StatusOK, resp)
293	}
