351	// linkProviders are the git forges whose brain keys map to real web URLs.
352	var linkProviders = map[string]bool{"gh": true, "gl": true, "bb": true}
353	
354	// parseRepoFromBrainDir recovers provider/owner/repo from the brain key that is
355	// the tail of brainDir (e.g. .../repos/gh/acme/app). Empty provider = a local
356	// repo with no forge, hence no web links.
357	func parseRepoFromBrainDir(brainDir string) (provider, owner, repo string) {
358		parts := strings.Split(strings.Trim(filepath.ToSlash(brainDir), "/"), "/")
359		if len(parts) < 3 {
360			return "", "", ""
361		}
362		p, o, r := parts[len(parts)-3], parts[len(parts)-2], parts[len(parts)-1]
363		if !linkProviders[p] || o == "" || r == "" {
364			return "", "", ""
365		}
366		return p, o, r
367	}
