420	func vizEdgeKey(a, b string) string {
421		if a > b {
422			return b + "|" + a
423		}
424		return a + "|" + b
425	}
426	
427	// linkBySharedKey connects nodes that share a key (a touched file, a locus token,
428	// a term). capPerKey bounds the fan-out so a widely-shared key can't explode the
429	// edge count.
430	// dedupEdges drops duplicate undirected edges (keeping the first), so combining
431	// several link passes (e.g. shared-topic + same-file) never double-counts a pair.
432	func dedupEdges(edges []vizGEdge) []vizGEdge {
433		seen := make(map[string]bool, len(edges))
434		out := edges[:0]
435		for _, e := range edges {
436			k := vizEdgeKey(e.From, e.To)
437			if seen[k] {
438				continue
439			}
440			seen[k] = true
441			out = append(out, e)
442		}
443		return out
444	}
445	
446	func linkBySharedKey(keyToIDs map[string][]string, typ string, capPerKey int) []vizGEdge {
447		var edges []vizGEdge
448		seen := map[string]bool{}
449		for _, ids := range keyToIDs {
450			if len(ids) < 2 {
451				continue
452			}
453			if capPerKey > 0 && len(ids) > capPerKey {
454				ids = ids[:capPerKey]
455			}
456			for i := 0; i < len(ids); i++ {
457				for j := i + 1; j < len(ids); j++ {
458					k := vizEdgeKey(ids[i], ids[j])
459					if seen[k] {
460						continue
461					}
462					seen[k] = true
463					edges = append(edges, vizGEdge{From: ids[i], To: ids[j], Type: typ})
464				}
465			}
466		}
467		return edges
468	}
