470	// factBranches lists the branches whose facts to show — the current branch first,
471	// then every branch the manifest records. Facts are branch-scoped on disk, but
472	// the Facts view is a whole-brain view, so it aggregates across branches.
473	func (s *vizServer) factBranches() []string {
474		out := []string{}
475		seen := map[string]bool{}
476		add := func(b string) {
477			b = strings.TrimSpace(b)
478			if b != "" && !seen[b] {
479				seen[b] = true
480				out = append(out, b)
481			}
482		}
483		add(s.branch)
484		if s.manifest != nil && s.manifest.Sources != nil && s.manifest.Sources.Facts != nil {
485			for _, b := range s.manifest.Sources.Facts.Branches {
486				add(b)
487			}
488		}
489		if len(out) == 0 {
490			out = append(out, s.branch)
491		}
492		return out
493	}
