495	func (s *vizServer) handleFacts(w http.ResponseWriter, r *http.Request) {
496		limit := vizQueryLimit(r, 3000)
497		seen := map[string]bool{}
498		all := []factRecord{}
499		var warnings []string
500		for _, br := range s.factBranches() {
501			fs, err := loadFacts(s.brainDir, br)
502			if err != nil {
503				warnings = append(warnings, "facts["+br+"]: "+err.Error())
504				continue
505			}
506			for _, f := range fs {
507				if f.ID != "" && seen[f.ID] {
508					continue
509				}
510				seen[f.ID] = true
511				all = append(all, f)
512			}
513		}
514		total := len(all)
515		trunc := limit > 0 && total > limit
516		if trunc {
517			all = all[:limit]
518		}
519		idset := map[string]bool{}
520		nodes := make([]vizGNode, 0, len(all))
521		locusMap := map[string][]string{}
522		for _, f := range all {
523			idset[f.ID] = true
524			link, label := "", ""
525			for _, a := range f.Provenance {
526				if a.SessionID != "" {
527					if l := s.sessionLink(a.SessionID); l != "" {
528						link, label = l, "Open source session in Entire"
529					}
530					break
531				}
532			}
533			conf := ""
534			if f.Confidence != "" {
535				conf = "conf " + f.Confidence
536			}
537			nodes = append(nodes, vizGNode{ID: f.ID, Name: vizShortLabel(f.Text, 6), Kind: f.Kind, Group: "fact", Color: colorFact, Text: f.Text, Meta: vizJoinMeta(f.Kind, f.Status, f.Origin, conf), Link: link, LinkLabel: label})
538			for _, l := range f.Locus {
539				key := strings.ToLower(strings.TrimSpace(l))
540				if key != "" {
541					locusMap[key] = append(locusMap[key], f.ID)
542				}
543			}
544		}
545		edges := []vizGEdge{}
546		relSeen := map[string]bool{}
547		for _, f := range all {
548			for _, rid := range f.RelatedIDs {
549				if !idset[rid] {
550					continue
551				}
552				k := vizEdgeKey(f.ID, rid)
553				if relSeen[k] {
554					continue
555				}
556				relSeen[k] = true
557				edges = append(edges, vizGEdge{From: f.ID, To: rid, Type: "related"})
558			}
559		}
560		edges = append(edges, linkBySharedKey(locusMap, "shared locus", 6)...)
561		writeJSONHTTP(w, http.StatusOK, vizFeatureGraph{Nodes: nodes, Edges: edges, Total: total, Truncated: trunc, Warnings: warnings})
562	}
