564	func (s *vizServer) handleSessions(w http.ResponseWriter, r *http.Request) {
565		limit := vizQueryLimit(r, 3000)
566		sessions := s.sessionsFromManifest()
567		total := len(sessions)
568		trunc := limit > 0 && total > limit
569		if trunc {
570			sessions = sessions[:limit]
571		}
572		nodes := make([]vizGNode, 0, len(sessions))
573		fileMap := map[string][]string{}
574		for _, se := range sessions {
575			created := ""
576			if !se.CreatedAt.IsZero() {
577				created = se.CreatedAt.UTC().Format("2006-01-02 15:04Z")
578			}
579			files := ""
580			if n := len(se.FilesTouched); n > 0 {
581				files = fmt.Sprintf("%d files", n)
582			}
583			cps := ""
584			if se.CheckpointsCount > 0 {
