630	// handleSessionReplay returns a session's touched-file symbols as a focused
631	// semantic subgraph plus an ordered, per-file step list. The UI "replays" the
632	// session across the code graph: light up each file's symbols in turn, tracing
633	// the path the agent took through the codebase.
634	func (s *vizServer) handleSessionReplay(w http.ResponseWriter, r *http.Request) {
635		id := strings.TrimSpace(r.URL.Query().Get("id"))
636		resp := vizReplayResp{Files: []string{}, Steps: []vizReplayStep{}, Nodes: []vizGNode{}, Edges: []vizGEdge{}}
637		if id == "" {
638			writeJSONHTTP(w, http.StatusBadRequest, vizReplayResp{Warnings: []string{"missing id"}})
639			return
640		}
641		sessions := s.sessionsFromManifest()
642		var se *exportSession
643		for i := range sessions {
644			if sessions[i].SessionID == id {
645				se = &sessions[i]
646				break
647			}
648		}
649		if se == nil {
650			writeJSONHTTP(w, http.StatusNotFound, vizReplayResp{Warnings: []string{"session not found: " + id}})
651			return
652		}
653	
654		created := ""
655		if !se.CreatedAt.IsZero() {
656			created = se.CreatedAt.UTC().Format("2006-01-02 15:04Z")
657		}
658		name := vizJoinMeta(se.Agent, se.Model)
659		if name == "" {
660			name = "session " + vizShortID(se.SessionID)
661		}
662		text := ""
663		if se.Summary != nil {
664			text = firstNonEmpty(se.Summary.Intent, se.Summary.Outcome)
665		}
666		link := s.sessionLink(se.SessionID)
667		sessLabel := ""
668		if link != "" {
669			sessLabel = "Open in Entire"
670		}
671		resp.Session = &vizGNode{
672			ID: se.SessionID, Name: name, Kind: se.Kind, Group: "session", Color: colorSession, Text: text,
673			Meta: vizJoinMeta(created, fmt.Sprintf("%d files", len(se.FilesTouched)), fmt.Sprintf("%d checkpoints", se.CheckpointsCount)),
674			Link: link, LinkLabel: sessLabel,
675		}
676	
677		touched := map[string]bool{}
678		for _, fp := range se.FilesTouched {
679			fp = strings.TrimSpace(filepath.ToSlash(fp))
680			if fp != "" && !touched[fp] {
681				touched[fp] = true
682				resp.Files = append(resp.Files, fp)
683			}
684		}
685		if len(resp.Files) == 0 {
686			resp.Warnings = append(resp.Warnings, "this session records no touched files")
687			writeJSONHTTP(w, http.StatusOK, resp)
688			return
689		}
690	
691		sem := s.semanticSource()
692		if sem == nil {
693			resp.Warnings = append(resp.Warnings, "no semantic graph — run `entire brain refresh`")
694			writeJSONHTTP(w, http.StatusOK, resp)
695			return
696		}
697		syms, err := loadSemanticSymbols(s.brainDir, sem, 0)
698		if err != nil {
699			resp.Warnings = append(resp.Warnings, "semantic symbols: "+err.Error())
700			writeJSONHTTP(w, http.StatusOK, resp)
701			return
702		}
703		byFile := map[string][]semanticRecord{}
704		for i := range syms {
705			f := filepath.ToSlash(syms[i].FilePath)
706			if touched[f] {
707				byFile[f] = append(byFile[f], syms[i])
708			}
709		}
710	
711		idset := map[string]bool{}
712		kept := []semanticRecord{}
713		for _, fp := range resp.Files {
714			step := vizReplayStep{File: fp, IDs: []string{}}
715			for i := range byFile[fp] {
716				sy := byFile[fp][i]
717				if !idset[sy.ID] {
718					if len(kept) >= vizReplayMaxNodes {
719						continue
720					}
721					idset[sy.ID] = true
722					kept = append(kept, sy)
723					resp.Nodes = append(resp.Nodes, vizGNode{
724						ID: sy.ID, Name: sy.Name, Kind: sy.Kind, Group: sy.Kind,
725						File: filepath.ToSlash(sy.FilePath), Line: sy.StartLine,
726						Link: s.sourceLink(sy.FilePath, sy.StartLine), LinkLabel: vizSourceLabel(s.provider),
727					})
728				}
729				step.IDs = append(step.IDs, sy.ID)
730			}
731			resp.Steps = append(resp.Steps, step)
732		}
733		resp.Total = len(resp.Nodes)
734	
735		if len(kept) > 0 {
736			if rels, rerr := s.relationsForSymbols(sem, kept, len(kept)*8); rerr == nil {
737				for i := range rels {
738					e := rels[i]
739					if idset[e.FromID] && idset[e.ToID] {
740						resp.Edges = append(resp.Edges, vizGEdge{From: e.FromID, To: e.ToID, Type: e.Type})
741					}
742				}
743			}
744		}
745		writeJSONHTTP(w, http.StatusOK, resp)
746	}
