766	func (s *vizServer) handleHistory(w http.ResponseWriter, r *http.Request) {
767		// History can hold hundreds of thousands of records — far too many to render
768		// legibly — so it stays capped (the UI shows an honest "N of total"), but the
769		// node-count slider lets you dial it up. Sessions/docs are shown in full.
770		limit := vizQueryLimit(r, 1200)
771		// Treat the 0 "no cap" sentinel as the ceiling too, so it can't slip past the
772		// safety bound and try to render every record on a very large brain.
773		if limit <= 0 || limit > vizGraphMaxView {
774			limit = vizGraphMaxView
775		}
776		if s.manifest == nil || s.manifest.Sources == nil || s.manifest.Sources.History == nil {
777			writeJSONHTTP(w, http.StatusOK, vizFeatureGraph{Nodes: []vizGNode{}, Edges: []vizGEdge{}, Warnings: []string{"no history yet — run `entire brain refresh`"}})
778			return
779		}
780		idx, err := loadBrainHistoryIndex(s.brainDir, s.manifest.Sources.History)
781		if err != nil {
782			writeJSONHTTP(w, http.StatusOK, vizFeatureGraph{Nodes: []vizGNode{}, Edges: []vizGEdge{}, Warnings: []string{"history unavailable: " + err.Error()}})
783			return
784		}
785		recs := idx.Records
786		total := len(recs)
787		trunc := limit > 0 && total > limit
788		if trunc {
789			recs = recs[:limit]
790		}
791		nodes := make([]vizGNode, 0, len(recs))
792		termMap := map[string][]string{}
793		pathMap := map[string][]string{}
794		for _, h := range recs {
795			nodes = append(nodes, vizGNode{ID: h.ID, Name: vizShortLabel(h.Summary, 7), Kind: h.Kind, Group: "history", Color: vizHistoryColor(h.Kind), Text: h.Summary, Meta: vizJoinMeta(h.Kind, h.Branch, h.Path)})
796			for _, t := range h.Terms {
797				key := strings.ToLower(strings.TrimSpace(t))
798				if len(key) > 2 {
799					termMap[key] = append(termMap[key], h.ID)
800				}
801			}
802			if p := strings.TrimSpace(filepath.ToSlash(h.Path)); p != "" {
803				pathMap[p] = append(pathMap[p], h.ID)
804			}
805		}
806		// Link by shared topic AND co-located history (same file); records touching
807		// the same file are related, which fills in the otherwise-sparse graph.
808		edges := append(linkBySharedKey(termMap, "shared topic", 8), linkBySharedKey(pathMap, "same file", 8)...)
809		// Timeline spine: chain consecutive records so history reads as one connected
810		// stream over time rather than a scatter of isolated points.
811		for i := 1; i < len(recs); i++ {
812			edges = append(edges, vizGEdge{From: recs[i-1].ID, To: recs[i].ID, Type: "then"})
813		}
814		edges = dedupEdges(edges)
815		writeJSONHTTP(w, http.StatusOK, vizFeatureGraph{Nodes: nodes, Edges: edges, Total: total, Truncated: trunc})
816	}
