867	func (s *vizServer) handleGraph(w http.ResponseWriter, r *http.Request) {
868		// `limit` is the number of symbols to RENDER (the node-count slider drives it).
869		// We load a wider pool, rank it by degree, and keep the top `limit` so the view
870		// is always the most-connected slice at any size the user picks.
871		view := vizGraphViewCap
872		if v := r.URL.Query().Get("limit"); v != "" {
873			if n, err := strconv.Atoi(v); err == nil && n > 0 {
874				view = n
875			}
876		}
877		if view > vizGraphMaxView {
878			view = vizGraphMaxView
879		}
880		// Scale the edge budget with the node count so a bigger view isn't artificially
881		// sparse. ~4 edges/node reads as a real constellation; floored so small views
882		// still show structure, ceilinged so a huge view can't blow up payload/draw.
883		edgeCap := view * 4
884		if edgeCap < 12000 {
885			edgeCap = 12000
886		}
887		if edgeCap > vizGraphMaxEdges {
888			edgeCap = vizGraphMaxEdges
889		}
890		resp := vizGraphResp{Nodes: []vizNode{}, Edges: []vizEdge{}}
891		sem := s.semanticSource()
892		if sem == nil {
893			resp.Warnings = append(resp.Warnings, "no semantic graph yet — run `entire brain refresh`")
894			writeJSONHTTP(w, http.StatusOK, resp)
895			return
896		}
897		pool := view * 3
898		if pool < 4000 {
899			pool = 4000
900		}
901		syms, err := loadSemanticSymbols(s.brainDir, sem, pool)
902		if err != nil {
903			resp.Warnings = append(resp.Warnings, "semantic symbols: "+err.Error())
904			writeJSONHTTP(w, http.StatusOK, resp)
905			return
906		}
907		if len(syms) == 0 {
908			resp.Warnings = append(resp.Warnings, "the semantic snapshot has no symbols yet — run `entire brain refresh`")
909			writeJSONHTTP(w, http.StatusOK, resp)
910			return
911		}
912		resp.Total = sem.Symbols
913	
914		// Rank the pool by degree so any `view` size keeps the most-connected symbols
915		// (loadSemanticSymbols returns storage order, so an unranked cap keeps leaves).
916		poolSet := make(map[string]bool, len(syms))
917		for i := range syms {
918			poolSet[syms[i].ID] = true
919		}
920		relLimit := pool * 4
921		var rels []semanticRecord
922		if r, rerr := s.relationsForSymbols(sem, syms, relLimit); rerr != nil {
923			resp.Warnings = append(resp.Warnings, "relations: "+rerr.Error())
924		} else {
925			rels = r
926		}
927		deg := make(map[string]int, len(syms))
928		for i := range rels {
929			e := rels[i]
930			if poolSet[e.FromID] && poolSet[e.ToID] {
931				deg[e.FromID]++
932				deg[e.ToID]++
933			}
934		}
935		kept := syms
936		if view > 0 && len(syms) > view {
937			ranked := make([]semanticRecord, len(syms))
938			copy(ranked, syms)
939			sort.SliceStable(ranked, func(i, j int) bool { return deg[ranked[i].ID] > deg[ranked[j].ID] })
940			kept = ranked[:view]
941		}
942		keptSet := make(map[string]bool, len(kept))
943		for i := range kept {
944			resp.Nodes = append(resp.Nodes, nodeJSON(kept[i]))
945			keptSet[kept[i].ID] = true
946		}
947		// Cap edges for render/sim budget, but choose them for COVERAGE first: a naive
948		// first-N cap piles all edges onto a few hubs and leaves most nodes edgeless, so
949		// they fly apart under repulsion and the whole graph fits to a dot. Pass 1 keeps
950		// edges that connect a still-unconnected node; pass 2 fills the remaining budget.
951		seen := make(map[string]bool)
952		covered := make(map[string]int)
953		addEdge := func(e semanticRecord) {
954			k := vizEdgeKey(e.FromID, e.ToID)
955			if seen[k] {
956				return
957			}
958			seen[k] = true
959			resp.Edges = append(resp.Edges, edgeJSON(e))
960			covered[e.FromID]++
961			covered[e.ToID]++
962		}
963		for i := range rels {
964			if len(resp.Edges) >= edgeCap {
965				break
966			}
967			e := rels[i]
968			if keptSet[e.FromID] && keptSet[e.ToID] && (covered[e.FromID] == 0 || covered[e.ToID] == 0) {
969				addEdge(e)
970			}
971		}
972		for i := range rels {
973			if len(resp.Edges) >= edgeCap {
974				break
975			}
976			e := rels[i]
977			if keptSet[e.FromID] && keptSet[e.ToID] {
978				addEdge(e)
979			}
980		}
981		resp.Truncated = sem.Symbols > len(kept)
982		writeJSONHTTP(w, http.StatusOK, resp)
983	}
