1023	func (s *vizServer) handleSearch(w http.ResponseWriter, r *http.Request) {
1024		q := strings.TrimSpace(r.URL.Query().Get("q"))
1025		limit := 25
1026		if v := r.URL.Query().Get("limit"); v != "" {
1027			if n, err := strconv.Atoi(v); err == nil && n > 0 {
1028				limit = n
1029			}
1030		}
1031		resp := vizSearchResp{Hits: []vizHit{}}
1032		if q == "" {
1033			writeJSONHTTP(w, http.StatusOK, resp)
1034			return
1035		}
1036		// Symbol matches first so ⌘K / rail search can jump straight to a graph node.
1037		if sem := s.semanticSource(); sem != nil {
1038			if syms, _, _, err := semanticContextFacts(s.brainDir, sem, q, limit, 0); err == nil {
1039				for _, sy := range syms {
1040					resp.Hits = append(resp.Hits, vizHit{Source: "symbol", ID: sy.ID, Title: sy.Name, Text: sy.QualifiedName, Kind: sy.Kind, Path: sy.FilePath, Line: sy.StartLine})
1041				}
1042			}
1043		}
1044		// Memory hits (facts / history / docs), same code path as `entire brain search`.
1045		if u, err := retrieveUnified(s.brainDir, s.branch, q, limit, modeLexical); err == nil {
1046			for _, h := range u {
1047				resp.Hits = append(resp.Hits, vizHit{Source: h.Source, ID: h.ID, Title: h.Heading, Text: h.Text, Path: h.Path, Line: h.Line, Score: h.Score})
1048			}
1049		}
1050		writeJSONHTTP(w, http.StatusOK, resp)
1051	}
