1053	// relationsForSymbols returns the relations among the given symbols, mirroring
1054	// the SQLite-vs-snapshot branch semanticContextFacts uses (semantic.go).
1055	func (s *vizServer) relationsForSymbols(sem *semanticSourceManifest, syms []semanticRecord, limit int) ([]semanticRecord, error) {
1056		if sem.StorePath != "" {
1057			storePath, err := validateSemanticDeclaredStore(s.brainDir, sem)
1058			if err != nil {
1059				return nil, err
1060			}
1061			return findSemanticRelationsForSymbolsInSQLite(storePath, syms, limit)
1062		}
1063		full, err := s.snapshotFullPath(sem)
1064		if err != nil {
1065			return nil, err
1066		}
1067		return findSemanticRelationsForSymbols(full, syms, limit)
1068	}
