1070	// nodeDetail resolves one symbol by exact id plus its relations and neighbors,
1071	// mirroring semanticContextFacts but seeded by id rather than a search query.
1072	func (s *vizServer) nodeDetail(sem *semanticSourceManifest, id string) (*semanticRecord, []semanticRecord, []semanticRecord, error) {
1073		const limit = 80
1074		if sem.StorePath != "" {
1075			storePath, err := validateSemanticDeclaredStore(s.brainDir, sem)
1076			if err != nil {
1077				return nil, nil, nil, err
1078			}
1079			byID, err := loadSemanticSymbolsByIDsSQLite(storePath, []string{id})
1080			if err != nil {
1081				return nil, nil, nil, err
1082			}
1083			node, ok := byID[id]
1084			if !ok {
1085				return nil, nil, nil, nil
1086			}
1087			rels, err := findSemanticRelationsForSymbolsInSQLite(storePath, []semanticRecord{node}, limit*4)
1088			if err != nil {
1089				return nil, nil, nil, err
1090			}
1091			neighbors, err := s.resolveNeighbors(node, rels, func(ids []string) (map[string]semanticRecord, error) {
1092				return loadSemanticSymbolsByIDsSQLite(storePath, ids)
1093			}, limit)
1094			if err != nil {
1095				return nil, nil, nil, err
1096			}
1097			return &node, neighbors, rels, nil
1098		}
1099		full, err := s.snapshotFullPath(sem)
1100		if err != nil {
1101			return nil, nil, nil, err
1102		}
1103		byID, err := loadSemanticSymbolsByIDsSnapshot(full, []string{id})
1104		if err != nil {
1105			return nil, nil, nil, err
1106		}
1107		node, ok := byID[id]
1108		if !ok {
1109			return nil, nil, nil, nil
1110		}
1111		rels, err := findSemanticRelationsForSymbols(full, []semanticRecord{node}, limit*4)
1112		if err != nil {
1113			return nil, nil, nil, err
1114		}
